430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Override
432	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
433	        Owner owner = this.clinicService.findOwnerById(ownerId);
434	        if (owner == null) {
435	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
436	        }
437	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
438	    }
439	
440	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
441	    @Override
442	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
443	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
444	        validateRequiredFields(ownerFieldsDto);
445	        LocalDate registrationDate = ownerFieldsDto.getRegistrationDate();
446	        if (registrationDate == null) {
447	            registrationDate = LocalDate.now();
448	        }
449	        registrationDate = toBusinessDay(registrationDate);
450	        ownerFieldsDto.setRegistrationDate(registrationDate);
451	        rejectDailyOwnerLimit(registrationDate);
452	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
453	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
454	        }
455	        rejectCityAtCapacity(ownerFieldsDto.getCity());
456	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
457	        rejectDuplicateTelephone(normalizedTelephone);
458	        ownerFieldsDto.setTelephone(normalizedTelephone);
459	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
460	        HttpHeaders headers = new HttpHeaders();
461	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
462	        owner.setCustomerCode(nextCustomerCode(ownerFieldsDto.getCity(), ownerFieldsDto.getLastName()));
463	        owner.setHouseholdId(householdId(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()));
464	        owner.setNamesakeCount(countNamesakes(ownerFieldsDto.getFirstName(), ownerFieldsDto.getLastName()));
465	        this.clinicService.saveOwner(owner);
466	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
467	        headers.setLocation(UriComponentsBuilder.newInstance()
468	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
469	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
470	    }
471	
472	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
473	    @Override
474	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
475	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
476	        if (currentOwner == null) {
477	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
478	        }
479	        currentOwner.setAddress(ownerFieldsDto.getAddress());
480	        currentOwner.setCity(ownerFieldsDto.getCity());
481	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
482	        currentOwner.setLastName(ownerFieldsDto.getLastName());
483	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
484	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
485	        this.clinicService.saveOwner(currentOwner);
486	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
487	    }
