501	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
502	    @Override
503	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
504	        Owner owner = this.clinicService.findOwnerById(ownerId);
505	        if (owner == null) {
506	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
507	        }
508	        HttpHeaders headers = new HttpHeaders();
509	        Pet pet = petMapper.toPet(petFieldsDto);
510	        owner.setId(ownerId);
511	        pet.setOwner(owner);
512	        pet.getType().setName(null);
513	        this.clinicService.savePet(pet);
514	        PetDto petDto = petMapper.toPetDto(pet);
515	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
516	            .buildAndExpand(pet.getId()).toUri());
517	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
518	    }
